from typing import List

def separate_paren_groups(paren_string: str) -> List[str]:
    paren_string = paren_string.replace(" ", "")  # Remove spaces from the input string
    result = []  # Initialize an empty list to store the separate strings
    group = ""  # Initialize an empty string to store each group of nested parentheses

    for char in paren_string:
        if char == '(':
            if group:
                result.append(group)
            group = "("
        elif char == ')':
            group += ")"
            result.append(group)
            group = ""

    return result

